package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.domain.SourceColumnMapping;import com.bombay.restaurantintelligence.repository.SourceColumnMappingRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/source-column-mappings") public class SourceColumnMappingController{private final SourceColumnMappingRepository repo;public SourceColumnMappingController(SourceColumnMappingRepository repo){this.repo=repo;}@GetMapping public List<View> list(@RequestParam String sourceKey){return repo.findBySourceKeyIgnoreCaseOrderBySourceColumn(sourceKey).stream().map(View::of).toList();}@PostMapping public View save(@Valid @RequestBody Request r){var current=repo.findFirstBySourceKeyIgnoreCaseAndSourceColumnIgnoreCase(r.sourceKey(),r.sourceColumn());if(current.isPresent())return View.of(current.get());return View.of(repo.save(new SourceColumnMapping(r.sourceKey(),r.sourceColumn(),r.canonicalField())));}public record Request(@NotBlank String sourceKey,@NotBlank String sourceColumn,@NotBlank String canonicalField){}public record View(UUID id,String sourceKey,String sourceColumn,String canonicalField){static View of(SourceColumnMapping m){return new View(m.getId(),m.getSourceKey(),m.getSourceColumn(),m.getCanonicalField());}}}
